CREATE TABLE "opname_hitung" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "opname_hitung_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"id_penyesuaian" bigint NOT NULL,
	"id_barang" bigint NOT NULL,
	"id_penghitung" bigint NOT NULL,
	"waktu" timestamp with time zone DEFAULT now() NOT NULL,
	"qty" numeric(14, 3) NOT NULL,
	"cara" varchar(7) DEFAULT 'HITUNG' NOT NULL,
	"berat_gram" numeric(14, 3),
	CONSTRAINT "chk_opname_hitung_cara" CHECK (cara in ('HITUNG','TIMBANG')),
	CONSTRAINT "chk_opname_hitung_qty" CHECK (qty >= 0),
	CONSTRAINT "chk_opname_hitung_berat" CHECK ((cara = 'TIMBANG') = (berat_gram is not null) and (berat_gram is null or berat_gram > 0))
);
