-- K-227: draf opname yang sudah berisi hasil hitung sebelum pembaruan: hasil itu dicatat sebagai hitungan pembuat draf.
INSERT INTO "opname_hitung" ("id_penyesuaian", "id_barang", "id_penghitung", "waktu", "qty", "cara")
SELECT d."id_penyesuaian", d."id_barang", p."id_pengguna", p."diubah_pada", d."qty_fisik", 'HITUNG'
  FROM "penyesuaian_stok_detail" d JOIN "penyesuaian_stok" p ON p."id" = d."id_penyesuaian"
 WHERE p."jenis" = 'OPNAME' AND p."status" = 'DRAFT' AND d."qty_fisik" IS NOT NULL AND NOT d."dikecualikan";
